Detailed information:
BUG TYPE:
    miscompilation

VERIFICATION RESULT:
    Invalid refinement in @pr135182 -- Value mismatch

VIOLATED PROPERTY:
    return-value equality

SOURCE (pre-transformation IR):
target datalayout = "e-m:e-p270:32:32-p271:32:32-p272:64:64-i64:64-i128:128-f80:128-n8:16:32:64-S128"

define i32 @pr135182() {
entry:
  br label %for.body

for.body:                                         ; preds = %for.body, %entry
  %indvar = phi i16 [ -12, %entry ], [ %indvar.next, %for.body ]
  %add = add i16 %indvar, %indvar
  %ext = zext i16 %add to i32
  %indvar.next = add i16 %indvar, 1
  br i1 false, label %for.body, label %for.end

for.end:                                          ; preds = %for.body
  ret i32 %ext
}

TARGET (post-transformation IR):
; ModuleID = '<stdin>'
source_filename = "<stdin>"
target datalayout = "e-m:e-p270:32:32-p271:32:32-p272:64:64-i64:64-i128:128-f80:128-n8:16:32:64-S128"

define i32 @pr135182() {
entry:
  br label %for.body

for.body:                                         ; preds = %for.body, %entry
  br i1 false, label %for.body, label %for.end

for.end:                                          ; preds = %for.body
  ret i32 131048
}

