  only in source:
    %indvar: %indvar = phi i16 [ -12, %entry ], [ %indvar.next, %for.body ]
    %add: %add = add i16 %indvar, %indvar
    %ext: %ext = zext i16 %add to i32
    %indvar.next: %indvar.next = add i16 %indvar, 1

CRITICAL VALUES:
    %add
    %ext
    %indvar
    %indvar.next

